from h import *

nueva('amanita-caesarea', cient='Amanita caesarea', sin=['Agaricus caesareus'], es=['oronja', 'amanita de los césares', 'huevo de rey', 'yema de huevo'],
  eu=['kuleto', 'kurrinto', 'xuringo', 'kuletro', 'gorringo', 'arrautza-perretxiko', 'gorrintxa'], grupo='laminar', clase='sin_datos', cand=True,
  nota='Es una Amanita: se parece a especies tóxicas como la matamoscas. Wikipedia la da como comestible «con una identificación correcta». Aquí queda como candidata sin confirmar.',
  clave='Sombrero naranja-rojo liso, láminas y pie AMARILLOS, anillo colgante y volva blanca en copa. Si el sombrero tiene verrugas blancas o las láminas son blancas, es otra Amanita.',
  mirar=[q('sombrero', 'Naranja a rojo, liso y estriado en el borde', 'Hasta 20 cm. Hemisférico, luego convexo y al final plano; liso, con el borde estriado. Sin verrugas.'),
         q('himenio', 'Láminas amarillentas', 'Apretadas y libres (o casi). Amarillentas, no blancas.'),
         q('pie', 'Amarillo, con anillo colgante', '5–15 cm, del color de las láminas o algo más pálido. El anillo cuelga flojo y suele estar estriado.'),
         q('volva', 'Copa blanca en la base', 'La base del pie está metida en una volva blanca en forma de copa (resto del velo universal): hay que desenterrarla. De joven es un huevo blanco cerrado.'),
         q('esporada', 'Esporada blanca', 'Blanca a amarillo muy pálido.'),
         q('habitat', 'Robles y pinos', 'Bosques de roble y de pino; en climas cálidos, robledales altos a veces mezclados con coníferas. De principios de verano a mediados de otoño.')],
  conf=[c('amanita-pantherina-muscaria', 'Amanita muscaria (matamoscas)', 'La oronja: sombrero liso, láminas, pie y anillo amarillos y volva blanca en copa. La matamoscas: sombrero con verrugas blancas y láminas blancas.', 'alta'),
        c(None, 'Otras Amanitas jóvenes (en estado de huevo)', 'En estado de huevo cerrado no se ven láminas ni anillo, que son lo que la distingue. El Gobierno de La Rioja pide no recoger oronjas en estado de huevo.', 'alta')],
  hab=['robledal', 'pinar'], habt='Principalmente robledales y pinares. En Europa: norte de África y sur de Europa, sobre todo las colinas del norte de Italia; en el País Vasco se cita como rara (apunte del catálogo inicial: verificar). Se piensa que los ejércitos romanos la llevaron al norte de los Alpes: se encuentra a menudo junto a antiguas calzadas romanas.',
  rec=dict(acc='extraer', txt='Sácala entera y desentierra la volva: es la clave. No la cojas en estado de huevo (Gobierno de La Rioja).'),
  esp='blanca',
  cur=['Su nombre viene de los emperadores romanos: «Caesar», el apellido de una familia, pasó a ser un título. Era una de sus setas favoritas.',
       'Giovanni Antonio Scopoli la describió en 1772. En Italia se llama «ovolo» (por el huevo) o «fungo reale».',
       'En euskera también se la llama «gorringo» («yema»): el sombrero que asoma de la volva recuerda a la yema de un huevo duro.',
       'En México se come asada con epazote. Un análisis encontró cadmio cuatro veces por encima de lo permitido para champiñón cultivado en la UE y plomo también por encima: los autores avisan de que comerla de forma crónica podría ser perjudicial.'],
  meses=[6, 7, 8, 9, 10], mnota='De principios de verano a mediados de otoño.', wp=['amanita-caesarea'], rioja=True)

nueva('agaricus-campestris', cient='Agaricus campestris', sin=['Psalliota campestris'], es=['champiñón de prado', 'hongo campesino', 'seta campesina'],
  eu=['barrengorri', 'xixa', 'azpibeltz', 'larre-sultso', 'sultso', 'txanpinoi', 'txurlo', 'xurlo', 'urdintxa'], grupo='laminar', clase='sin_datos', cand=True,
  nota='Es la «xixa» (champiñón silvestre). Se confunde con la Amanita virosa mortal y con el Agaricus xanthodermus tóxico. Wikipedia la da como comestible «con cuidado para distinguirla de las venenosas».',
  clave='Champiñón de prado: láminas ROSAS que pasan a pardo chocolate y un anillo fino. NUNCA con volva ni con láminas blancas (Amanita mortal). Si al cortar la base se pone amarillo vivo: no.',
  mirar=[q('sombrero', 'Blanco, a veces con escamitas', '3–12 cm. Primero hemisférico y luego aplanado; blanco, puede tener escamas finas.'),
         q('himenio', 'Láminas rosa → pardo chocolate', 'Rosa vivo al principio, luego rojo pardo y al final pardo oscuro, como la esporada. Nunca blancas.'),
         q('pie', 'Blanco con un anillo fino', '3–10 cm, de 1–2 cm de ancho, casi todo blanco y con un solo anillo delgado.'),
         q('carne', 'Se pone pardo-rojiza', 'Blanca; al magullarla se vuelve pardo rojiza sucia, no amarilla (eso es lo que hace A. xanthodermus). Sabor suave.'),
         q('esporada', 'Esporada pardo oscuro', 'Pardo oscuro. Las Amanitas dan esporada blanca.'),
         q('habitat', 'Prados y césped, no bosque', 'Campos y zonas de hierba tras la lluvia desde finales de verano; a menudo en céspedes urbanos, en grupos, en corros o sola. Rara en bosque.')],
  conf=[c('amanita-verna-virosa', 'Amanita virosa (ángel destructor)', 'La más peligrosa: mortal. La Amanita tiene volva en la base y esporada blanca; el champiñón no tiene volva y su esporada es pardo oscura. Busca setitas jóvenes cerca y córtalas a lo largo para ver su interior: una Amanita joven aún lleva el velo (la futura volva) rodeándola.', 'alta'),
        c('agaricus-xanthodermus', 'Agaricus xanthodermus', 'La confusión más frecuente: amarillea al instante al cortar la base y huele a fenol; da problemas digestivos a mucha gente.', 'media'),
        c(None, 'Agaricus arvensis', 'Muy parecido, y excelente comestible según Wikipedia. Casi idéntico salvo al microscopio.', 'baja'),
        c('clitocybe-rivulosa', 'Clitocybes blancas de prado', 'Algunas Clitocybe blancas que salen en prados pueden ser tóxicas. Mira las láminas: las del champiñón son rosas al principio.', 'alta')],
  hab=['prado', 'parque'], habt='Campos y pastos tras la lluvia, desde finales de verano; también céspedes de jardines y parques. Se cría en grupos, en «corros de brujas» o solitaria. Antes aparecían «campos blancos» enteros: hoy son raros por haber menos caballos pastando.',
  rec=dict(acc='extraer', txt='Sácala entera, con la base, para poder descartar una Amanita. Tamaño mínimo de La Rioja para Agaricus: 4 cm. No la cojas de céspedes tratados con pesticidas (Wikipedia avisa de que podrían estar contaminados).'),
  esp='pardo oscuro',
  cur=['Linneo la describió en 1753. No se cultiva comercialmente porque madura deprisa y dura poco.',
       'Hay casos en Francia de personas que comieron Amanita virosa creyendo que era esta seta.',
       'Es pariente cercana del champiñón de cultivo (A. bisporus).',
       'En euskera tiene muchísimos nombres locales; «xixa» es uno de ellos.'],
  meses=[8, 9, 10, 11], mnota='Desde finales de verano.', wp=['agaricus-campestris'], rioja=True)

nueva('agaricus-xanthodermus', cient='Agaricus xanthodermus', sin=['Psalliota xanthoderma'], es=[], eu=['azpibeltz tintausain argia'], grupo='laminar', clase='toxica', cand=False,
  clave='Champiñón blanco que, al cortar la base del pie o raspar, se pone AMARILLO vivo al instante, y huele a tinta o a jabón fenólico. Da retortijones.',
  mirar=[q('carne', 'Amarillo vivo al corte', 'Es el rasgo clave: color amarillo inmediato al cortar la base del pie o raspar la carne; luego se apaga a pardo.'),
         q('olor', 'Olor desagradable, «a fenol»', 'Un olor dulzón y repugnante, como a jabón carbólico, más fuerte en la base del pie. Al cocinarla se nota muchísimo.'),
         q('sombrero', 'Blanquecino con tonos pardos', '5–15 cm. Convexo, a veces casi cuadrado de joven, aplanado con la edad; blanquecino con tintes pardo claro al centro; seco y liso, escamoso en los viejos.'),
         q('himenio', 'Láminas rosa pálido → chocolate', 'Como en otros Agaricus.'),
         q('pie', 'Bulboso con anillo en falda', 'Blanco, 5–12 cm, con la base abultada (bulbo) y un anillo grande tipo falda.'),
         q('habitat', 'Bosques, céspedes y setos', 'En bosques, césped, jardines y setos, en otoño.')],
  conf=[c('agaricus-campestris', 'Agaricus campestris (xixa) y otros champiñones comestibles', 'Varios Agaricus comestibles (A. arvensis, A. augustus, A. silvicola) amarillean un poco, pero no de forma tan intensa y no huelen a fenol. La xixa se pone pardo-rojiza.', 'media')],
  hab=['bosque', 'parque', 'cuneta'], habt='Muy común y extendida en Europa, Norteamérica, norte de África y sur de África. Crece en bosques, céspedes, jardines y setos en otoño. Es saprobia.',
  rec=dict(acc='dejar', txt='No se coge. Wikipedia dice que alrededor del 50 % de las intoxicaciones entre quienes recogen champiñones silvestres son por esta especie. Compruébalo siempre cortando la base.'),
  sind='Trastorno gastrointestinal grave: sudor, enrojecimiento, calambres abdominales fuertes, náuseas y diarrea; menos común, dolor de cabeza. Es indigesta. Algunas personas parecen tolerarla.', lat=None, grav=None,
  cur=['La definió León Gaston Genevier en 1876 en una carta publicada en el boletín de la Sociedad Botánica de Francia.',
       'En Italia está expresamente prohibida su venta.',
       'Pertenece a un grupo de champiñones (los «Xanthodermati») que amarillean y huelen a fenol.',
       'Por el olor a fenol que se nota al cocinarla, mucha gente la deja de comer a tiempo.'],
  meses=[9, 10, 11], mnota='Otoño.', wp=['agaricus-xanthodermus'], rioja=False)

nueva('coprinus-comatus', cient='Coprinus comatus', sin=['Agaricus comatus'], es=[], eu=['urbeltz galpardun', 'lederkia'], grupo='laminar', clase='sin_datos', cand=True,
  clave='Sombrero blanco alargado como un cilindro con escamas; las láminas pasan de blanco a rosa y se deshacen en tinta negra. Solo jóvenes, y en el día.',
  mirar=[q('sombrero', 'Cilindro blanco y lanudo', '4–8 cm de ancho y 6–20 cm de alto. Casi cilíndrico, cubre casi todo el pie al principio. Blanco con escamas más pardas en el ápice.'),
         q('himenio', 'Láminas que se licúan', 'Libres; cambian rápido de blanco a rosa y después se deshacen en un líquido negro cargado de esporas (de ahí «hongo de tinta»).'),
         q('pie', 'Blanco, largo y con anillo suelto', '6–40 cm de alto, blanco y bastante grueso, con un anillo suelto cerca de la base.'),
         q('carne', 'Blanca, sabor suave', 'Carne blanca y sabor suave.'),
         q('esporada', 'Esporada negra', 'Negro-parda.'),
         q('habitat', 'Hierba, terreno removido', 'En praderas y prados, en grupos; también terrenos removidos, bordes de caminos, parques y escombreras, de primavera a finales de otoño.')],
  conf=[c('coprinopsis-atramentaria', 'Coprinopsis atramentaria', 'Parecida; contiene coprina, que causa intoxicación sobre todo si se toma con alcohol.', 'media'),
        c(None, 'Coprinopsis picacea (seta urraca)', 'Venenosa; también se confunde con esta.', 'media')],
  hab=['prado', 'parque', 'cuneta'], habt='Praderas y prados bien abonados, bordes de caminos, parques y escombreras; solitaria o en grupos, y a veces en corros de brujas.',
  rec=dict(acc='cortar', txt='Recoge solo ejemplares jóvenes, con las láminas aún blancas, y prepáralos pronto: las zonas negras se vuelven amargas. Wikipedia en español aconseja consumirla el mismo día porque se pudre con facilidad.'),
  esp='negro-pardo',
  cur=['Come nematodos: es un hongo nematófago capaz de matar y digerir gusanos del suelo.',
       'Su nombre viene de «coma», cabello, por sus escamas lanudas.',
       'Una pariente parecida (C. atramentaria) provoca síntomas con alcohol por la coprina; Wikipedia indica que esta especie no la tiene.',
       'La describió el naturalista danés Otto Friedrich Müller en 1780.'],
  meses=[3, 4, 5, 6, 7, 8, 9, 10, 11], mnota='De primavera a finales de otoño (junio–noviembre en el Reino Unido).', wp=['coprinus-comatus'], rioja=False)
